def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    def opp_at(i):
        return history[i][1]

    def me_at(i):
        return history[i][0]

    c_opp = sum(1 for i in range(n) if opp_at(i) == 'C')
    d_opp = n - c_opp
    my_d = sum(1 for i in range(n) if me_at(i) == 'D')

    # Exploit if we defected and opponent never retaliated
    if my_d > 0:
        retaliations = 0
        my_d_instances = 0
        for i in range(1, n):
            if me_at(i - 1) == 'D':
                my_d_instances += 1
                if opp_at(i) == 'D':
                    retaliations += 1
        if my_d_instances > 0 and retaliations == 0:
            return 'D'
        if n >= 1 and me_at(n - 1) == 'D' and opp_at(n - 1) == 'C':
            return 'D'

    # Check if opponent mirrors our previous move (TFT-like)
    if my_d > 0 and n >= 2:
        mirror_score = 0
        for i in range(1, n):
            if opp_at(i) == me_at(i - 1):
                mirror_score += 1
        if mirror_score >= (n - 1) * 0.7:
            if n >= 99:
                return 'D'
            return 'C'

    # Detect simple always cooperate / always defect
    if d_opp == 0:
        if n >= 10:
            return 'D'
        return 'C'
    if c_opp == 0:
        return 'D'

    last = opp_at(n - 1)
    last2 = opp_at(n - 2) if n >= 2 else 'C'
    last3 = opp_at(n - 3) if n >= 3 else 'C'

    streak_d = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'D':
        streak_d += 1
        i -= 1

    streak_c = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'C':
        streak_c += 1
        i -= 1

    coop_rate = c_opp / n

    remaining = 100 - n
    if remaining <= 5:
        if coop_rate > 0.6 and streak_d == 0:
            return 'D'
        if coop_rate > 0.75:
            return 'D'
        return 'C'

    if streak_d >= 2:
        return 'D'

    if streak_d == 1:
        if me_at(n - 1) == 'D':
            if coop_rate > 0.7 and streak_c >= 3:
                return 'C'
            if n >= 4 and opp_at(n - 3) == 'C' and opp_at(n - 4) == 'C':
                return 'C'
        return 'D'

    if coop_rate >= 0.8:
        return 'C'

    if n >= 6:
        alt_score = 0
        for i in range(1, n):
            if opp_at(i) != opp_at(i - 1):
                alt_score += 1
        if alt_score >= n - 2:
            if last == 'C':
                return 'D'
            return 'C'

    if last == 'C':
        return 'C'
    else:
        if coop_rate > 0.6 and streak_d <= 1:
            return 'C'
        if coop_rate > 0.5 and rng.random() < 0.3:
            return 'C'
        return 'D'
